import { NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { buildSampleUniversityCsv } from '@/lib/university-sample';

/**
 * The template for a university profile CSV.
 *
 * Served rather than kept as a static file so it is generated by the same
 * codebase that parses it — see the test that imports this exact output.
 */
export async function GET() {
  const session = await getServerSession(authOptions);
  if (!session) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

  return new NextResponse(buildSampleUniversityCsv(), {
    headers: {
      'Content-Type': 'text/csv; charset=utf-8',
      'Content-Disposition': 'attachment; filename="university-profile-sample.csv"',
      'Cache-Control': 'no-store',
    },
  });
}
